#[derive(Debug, Clone, Copy)] pub struct DeterministicRng { state:u64 }
impl DeterministicRng { pub fn new(seed:u64)->Self{Self{state:if seed==0{0x9E3779B97F4A7C15}else{seed}}} pub fn next_u64(&mut self)->u64{let mut x=self.state;x^=x<<13;x^=x>>7;x^=x<<17;self.state=x;x} pub fn next_u32(&mut self)->u32{self.next_u64() as u32} pub fn range_u32(&mut self,min:u32,max_exclusive:u32)->u32{if min>=max_exclusive{return min;} min+self.next_u32()%(max_exclusive-min)} pub fn chance(&mut self,probability:f32)->bool{let p=probability.clamp(0.0,1.0);(self.next_u64() as f64/u64::MAX as f64)<p as f64} }
